"use client";

import { useState, useEffect, useCallback } from "react";
import type { ChatMessage, Conversation, ConversationResponse } from "@/app/types/chat";
import { createConversation, createMessage, createId, deriveTitle } from "@/lib/chatStorage";
import ChatSidebar from "@/components/chat/ChatSidebar";
import ChatMessages from "@/components/chat/ChatMessages";
import ChatInput from "@/components/chat/ChatInput";
import AgentSelector from "@/components/chat/AgentSelector";
import { AGENT_DEFINITIONS, type AgentId } from "@/lib/agents";
import { parseImageAttachment } from "@/lib/multimodal";

type SpeechRecognitionLike = {
  lang: string;
  continuous: boolean;
  interimResults: boolean;
  start: () => void;
  stop: () => void;
  onresult: ((event: Event) => void) | null;
  onerror: ((event: Event) => void) | null;
  onend: (() => void) | null;
};

type ChatClientProps = {
  user: {
    id: string;
    name?: string | null;
    email?: string | null;
  };
};

export default function ChatClient({ user }: ChatClientProps) {
  const [hydrated, setHydrated] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [conversations, setConversations] = useState<Conversation[]>([]);
  const [activeId, setActiveId] = useState<string | null>(null);
  const activeConversation = conversations.find((c) => c.id === activeId) ?? null;
  const messages = activeConversation?.messages ?? [];
  const [input, setInput] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [uploadingFileName, setUploadingFileName] = useState<string | null>(null);
  const [uploadStatus, setUploadStatus] = useState<string | null>(null);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [assistantMessageId, setAssistantMessageId] = useState<string | null>(null);
  const [abortController, setAbortController] = useState<AbortController | null>(null);
  const [isRecording, setIsRecording] = useState(false);
  const [voiceStatus, setVoiceStatus] = useState<string | null>(null);
  const [imagePreview, setImagePreview] = useState<string | null>(null);
  const [imageAttachment, setImageAttachment] = useState<string | null>(null);
  const [recognition, setRecognition] = useState<SpeechRecognitionLike | null>(null);
  const [activeAgent, setActiveAgent] = useState<AgentId>("general");
  const [routedAgent, setRoutedAgent] = useState<AgentId | null>(null);
  const [conversationAgents, setConversationAgents] = useState<Record<string, AgentId>>(() => {
    if (typeof window === "undefined") return {};
    try {
      const stored = window.localStorage.getItem("india-digital-brain-agents");
      if (!stored) return {};
      const parsed = JSON.parse(stored) as Record<string, AgentId>;
      return parsed;
    } catch {
      return {};
    }
  });

  useEffect(() => {
    if (typeof window !== "undefined") {
      window.localStorage.setItem("india-digital-brain-agents", JSON.stringify(conversationAgents));
    }
  }, [conversationAgents]);

  useEffect(() => {
    if (activeId) {
      setActiveAgent(conversationAgents[activeId] ?? "general");
      setRoutedAgent(null);
    }
  }, [activeId, conversationAgents]);

  useEffect(() => {
    if (typeof window === "undefined") return;

    const SpeechRecognitionCtor =
      (window as Window & typeof globalThis & { SpeechRecognition?: new () => SpeechRecognitionLike }).SpeechRecognition ||
      (window as Window & typeof globalThis & { webkitSpeechRecognition?: new () => SpeechRecognitionLike }).webkitSpeechRecognition;

    if (!SpeechRecognitionCtor) {
      setVoiceStatus("Voice input is not supported in this browser.");
      return;
    }

    const recognitionInstance = new SpeechRecognitionCtor();
    recognitionInstance.lang = "en-IN";
    recognitionInstance.continuous = false;
    recognitionInstance.interimResults = true;

    recognitionInstance.onresult = (event: Event & { results?: ArrayLike<ArrayLike<{ transcript?: string }>> }) => {
      const results = event.results ?? [];
      const transcript = Array.from(results)
        .map((result) => result[0]?.transcript ?? "")
        .join(" ");
      setInput(transcript);
      setVoiceStatus("Voice capture complete.");
    };

    recognitionInstance.onerror = () => {
      setVoiceStatus("Voice capture failed. Please try again.");
      setIsRecording(false);
    };

    recognitionInstance.onend = () => {
      setIsRecording(false);
      setVoiceStatus(null);
    };

    setRecognition(recognitionInstance);
  }, []);

  useEffect(() => {
    async function loadHistory() {
      setIsRefreshing(true);
      try {
        const res = await fetch("/api/conversations", { cache: "no-store" });
        const data = await res.json();
        if (res.ok && data.success && data.conversations?.length > 0) {
          const apiConversations: Array<{
            id: string;
            title: string;
            createdAt: string;
            updatedAt: string;
          }> = data.conversations;

          // Convert API summaries to the client Conversation shape.
          const mapped: Conversation[] = apiConversations.map((c) => ({
            id: c.id,
            title: c.title,
            messages: [],
            updatedAt: new Date(c.updatedAt).getTime(),
            isLocal: false,
          }));

          // Fetch the first page of messages for the most recent conversation.
          const first = mapped[0];
          if (first) {
            try {
              const msgRes = await fetch(
                `/api/conversations/${first.id}/messages?page=1&pageSize=50`,
                { cache: "no-store" }
              );
              const msgData = await msgRes.json();
              if (msgRes.ok && msgData.success) {
                first.messages = msgData.messages.map(
                  (m: {
                    id: string;
                    role: string;
                    content: string;
                    isError?: boolean;
                    createdAt: string;
                  }) => ({
                    id: m.id,
                    role: m.role === "assistant" ? "assistant" : "user",
                    message: m.content,
                    createdAt: new Date(m.createdAt).getTime(),
                    ...(m.isError ? { isError: true } : {}),
                  })
                );
              }
            } catch {
              // If the messages fetch fails, keep the empty conversation.
            }
          }

          setConversations(mapped);
          setActiveId(mapped[0]?.id ?? null);
        } else {
          // No persisted conversations yet ΓÇö create one locally (it will be
          // persisted to the server on the first send via POST /api/conversations).
          const fresh = createConversation();
          setConversations([fresh]);
          setActiveId(fresh.id);
        }
      } catch {
        const fresh = createConversation();
        setConversations([fresh]);
        setActiveId(fresh.id);
      } finally {
        setHydrated(true);
        setIsRefreshing(false);
      }
    }

    loadHistory();
  }, []);

  const updateMessages = useCallback(
    (updater: (prev: ChatMessage[]) => ChatMessage[], conversationId: string | null = activeId) => {
      setConversations((prev) => {
        const updated = prev.map((c) => {
          if (c.id !== conversationId) return c;
          return {
            ...c,
            messages: updater(c.messages),
            updatedAt: Date.now(),
          };
        });
        return updated.sort((a, b) => b.updatedAt - a.updatedAt);
      });
    },
    [activeId]
  );

  const updateAssistantMessage = useCallback(
    (message: string, isError = false) => {
      if (!assistantMessageId) return;
      updateMessages((prev) =>
        prev.map((messageItem) =>
          messageItem.id === assistantMessageId
            ? { ...messageItem, message, isError }
            : messageItem
        )
      );
    },
    [assistantMessageId, updateMessages]
  );

  function resetMultimodalState() {
    setImagePreview(null);
    setImageAttachment(null);
    setVoiceStatus(null);
  }

  async function newConversation() {
    // Create a persisted conversation via the new Phase 4 API. If it fails,
    // fall back to a local conversation so the UI remains usable.
    let fresh = createConversation();
    try {
      const res = await fetch("/api/conversations", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ title: "New chat" }),
      });
      const data = await res.json();
      if (res.ok && data.success) {
        fresh = {
          id: data.conversation.id,
          title: data.conversation.title,
          messages: [],
          updatedAt: new Date(data.conversation.updatedAt).getTime(),
          isLocal: false,
        };
      }
    } catch {
      // Fall back to the local conversation.
    }

    setConversations((prev) => [fresh, ...prev]);
    setActiveId(fresh.id);
    setInput("");
    setActiveAgent("general");
    resetMultimodalState();
    setSidebarOpen(false);
  }

  function handleAgentChange(nextAgent: AgentId) {
    setActiveAgent(nextAgent);
    setRoutedAgent(null);
    if (activeId) {
      setConversationAgents((prev) => ({ ...prev, [activeId]: nextAgent }));
    }
  }

  function toggleVoiceRecording() {
    if (!recognition) {
      setVoiceStatus("Voice input is not supported in this browser.");
      return;
    }

    if (isRecording) {
      recognition.stop();
      setIsRecording(false);
      setVoiceStatus("Stopping voice recording...");
      return;
    }

    setIsRecording(true);
    setVoiceStatus("Listening...");
    recognition.start();
  }

  function removeImage() {
    setImagePreview(null);
    setImageAttachment(null);
    setUploadStatus(null);
  }

  async function deleteConversation(id: string) {
    try {
      await fetch(`/api/conversations/${encodeURIComponent(id)}`, {
        method: "DELETE",
      });
    } catch {
      // Allow local deletion even if server request fails.
    }

    setConversations((prev) => {
      const next = prev.filter((c) => c.id !== id);
      if (activeId === id) {
        setActiveId(next.length > 0 ? next[0].id : null);
        if (next.length === 0) {
          const fresh = createConversation();
          setActiveId(fresh.id);
          return [fresh];
        }
      }
      return next;
    });
  }

  async function sendMessage() {
    const text = input.trim();
    if ((!text && !imageAttachment) || isLoading || isUploading) return;

    let currentId = activeId;
    let currentConversation = activeConversation;

    if (!currentConversation) {
      const fresh = createConversation(deriveTitle(text));
      setConversations((prev) => [fresh, ...prev]);
      setActiveId(fresh.id);
      currentId = fresh.id;
      currentConversation = fresh;
    }

    const title =
      currentConversation.title === "New chat" && currentConversation.messages.length === 0
        ? deriveTitle(text)
        : currentConversation.title;

    if (
      currentConversation.title === "New chat" &&
      currentConversation.messages.length === 0
    ) {
      setConversations((prev) =>
        prev.map((c) => (c.id === currentId ? { ...c, title } : c))
      );
    }

    const userMsg = createMessage("user", text || (imageAttachment ? "[Image attached]" : ""));
    const assistantId = createId();
    const assistantMsg: ChatMessage = {
      ...createMessage("assistant", ""),
      id: assistantId,
    };

    updateMessages((prev) => [...prev, userMsg, assistantMsg], currentId);
    setAssistantMessageId(assistantId);
    setInput("");
    setIsLoading(true);
    resetMultimodalState();

    const controller = new AbortController();
    setAbortController(controller);

    try {
      const response = await fetch("/api/chat", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          message: text,
          conversationId: currentId,
          conversationTitle: title,
          agent: activeAgent,
          image: imageAttachment,
        }),
        signal: controller.signal,
      });

      const updateStreamingAssistantMessage = (message: string, isError = false) => {
        updateMessages(
          (prev) =>
            prev.map((messageItem) =>
              messageItem.id === assistantId
                ? { ...messageItem, message, isError }
                : messageItem
            ),
          currentId
        );
      };

      if (!response.ok) {
        const errorPayload = await response.json().catch(() => null);
        const errorMessage =
          errorPayload?.error ||
          "Failed to stream AI response. Please try again.";
        updateStreamingAssistantMessage(errorMessage, true);
        return;
      }

      if (!response.body) {
        updateStreamingAssistantMessage(
          "AI stream unavailable. Please try again.",
          true
        );
        return;
      }

      const reader = response.body.getReader();
      const decoder = new TextDecoder();
      let buffer = "";
      let partial = "";
      let finished = false;

      const processLine = (line: string) => {
        const trimmed = line.trim();
        if (!trimmed) return;

        try {
          const payload = JSON.parse(trimmed) as {
            type?: string;
            text?: string;
            reply?: string;
            error?: string;
            retrievedDocumentTitles?: string[];
            sourcePaths?: string[];
            ragUsed?: boolean;
            agent?: AgentId;
            agentName?: string;
            agentIcon?: string;
            routed?: boolean;
            usedToolId?: string | null;
            usedToolLabel?: string | null;
            // Phase 8 ΓÇö multi-agent fields
            agents?: string[];
            agentNames?: string[];
            agentIcons?: string[];
            usedToolIds?: string[];
            usedToolLabels?: string[];
          };

          if (payload.type === "chunk" && typeof payload.text === "string") {
            partial += payload.text;
            updateStreamingAssistantMessage(partial);
          }

          if (payload.type === "done" && typeof payload.reply === "string") {
            finished = true;
            updateStreamingAssistantMessage(payload.reply);

            // Phase 7 ΓÇö attach the tool-usage indicator to the assistant
            // message so the bubble can render e.g. "≡ƒº« Calculator".
            if (payload.usedToolId && payload.usedToolLabel) {
              updateMessages(
                (prev) =>
                  prev.map((messageItem) =>
                    messageItem.id === assistantId
                      ? {
                          ...messageItem,
                          usedToolId: payload.usedToolId ?? undefined,
                          usedToolLabel: payload.usedToolLabel ?? undefined,
                        }
                      : messageItem
                  ),
                currentId
              );
            }

            // Phase 8 ΓÇö attach all participating agents and all tool usage
            // across agents to the assistant message.
            if (payload.agents && payload.agents.length > 0) {
              updateMessages(
                (prev) =>
                  prev.map((messageItem) =>
                    messageItem.id === assistantId
                      ? {
                          ...messageItem,
                          agents: payload.agents,
                          agentNames: payload.agentNames,
                          agentIcons: payload.agentIcons,
                          usedToolIds: payload.usedToolIds,
                          usedToolLabels: payload.usedToolLabels,
                        }
                      : messageItem
                  ),
                currentId
              );
            }

            // When the server routed the query to a specialist agent, surface
            // it in the UI so the user can see which agent answered.
            if (payload.agent && payload.routed) {
              setRoutedAgent(payload.agent);
              setActiveAgent(payload.agent);
              if (currentId) {
                setConversationAgents((prev) => ({
                  ...prev,
                  [currentId]: payload.agent as AgentId,
                }));
              }
            }
          }

          if (payload.type === "error" && typeof payload.error === "string") {
            updateStreamingAssistantMessage(payload.error, true);
          }
        } catch {
          // Ignore invalid partial lines.
        }
      };

      while (true) {
        const { done, value } = await reader.read();
        if (done) break;

        buffer += decoder.decode(value, { stream: true });
        const lines = buffer.split("\n");
        buffer = lines.pop() ?? "";

        for (const line of lines) {
          processLine(line);
        }
      }

      if (buffer.trim()) {
        processLine(buffer);
      }

      const trailing = decoder.decode();
      if (trailing) {
        const lines = (buffer + trailing).split("\n");
        buffer = lines.pop() ?? "";

        for (const line of lines) {
          processLine(line);
        }
      }

      if (!finished && partial) {
        updateStreamingAssistantMessage(partial);
      }
    } catch (error: unknown) {
      const isAbort =
        typeof error === "object" &&
        error !== null &&
        "name" in error &&
        (error as { name?: string }).name === "AbortError";

      if (!isAbort) {
        updateMessages(
          (prev) =>
            prev.map((messageItem) =>
              messageItem.id === assistantId
                ? { ...messageItem, message: "Γ¥î Failed to contact AI. Please check your connection and try again.", isError: true }
                : messageItem
            ),
          currentId
        );
      }
    } finally {
      setIsLoading(false);
      setAbortController(null);
      setAssistantMessageId(null);
    }
  }

  async function handleFileAttach(file: File) {
    if (isUploading || isLoading) return;

    if (file.type.startsWith("image/")) {
      const reader = new FileReader();
      reader.onload = () => {
        const result = reader.result;
        if (typeof result === "string") {
          const parsed = parseImageAttachment(result);
          if (parsed) {
            setImagePreview(result);
            setImageAttachment(result);
            setUploadStatus(`Image ready: ${file.name}`);
          } else {
            setUploadStatus("Unsupported image payload.");
          }
        }
      };
      reader.readAsDataURL(file);
      return;
    }

    let currentId = activeId;
    let currentConversation = activeConversation;

    if (!currentConversation) {
      const fresh = createConversation();
      setConversations((prev) => [fresh, ...prev]);
      setActiveId(fresh.id);
      currentId = fresh.id;
      currentConversation = fresh;
    }

    const title =
      currentConversation.title === "New chat" && currentConversation.messages.length === 0
        ? deriveTitle(`Uploaded file: ${file.name}`)
        : currentConversation.title;

    if (
      currentConversation.title === "New chat" &&
      currentConversation.messages.length === 0
    ) {
      setConversations((prev) =>
        prev.map((c) => (c.id === currentId ? { ...c, title } : c))
      );
    }

    const userMsg = createMessage("user", `Uploaded file: ${file.name}`);
    const assistantId = createId();
    const assistantMsg: ChatMessage = {
      ...createMessage("assistant", ""),
      id: assistantId,
    };

    updateMessages((prev) => [...prev, userMsg, assistantMsg]);
    setAssistantMessageId(assistantId);
    setIsUploading(true);
    setUploadingFileName(file.name);
    setUploadStatus("Uploading file...");

    try {
      const formData = new FormData();
      formData.append("file", file);
      formData.append("conversationId", currentId ?? "");

      const response = await fetch("/api/chat/upload", {
        method: "POST",
        body: formData,
      });

      const result = await response.json().catch(() => null);
      if (!response.ok || !result?.success) {
        const errorMessage =
          result?.error || "Failed to upload file. Please try again.";
        setUploadStatus(errorMessage);
        updateAssistantMessage(errorMessage, true);
        return;
      }

      const successMessage =
        result.message || `Uploaded and processed ${file.name}.`;
      setUploadStatus(successMessage);
      updateAssistantMessage(successMessage);
    } catch (error) {
      const message = "Failed to upload file. Please check your connection.";
      setUploadStatus(message);
      updateAssistantMessage(message, true);
    } finally {
      setIsUploading(false);
      setUploadingFileName(null);
      setTimeout(() => setUploadStatus(null), 5000);
      setAssistantMessageId(null);
    }
  }

  function stopGenerating() {
    abortController?.abort();
    setAbortController(null);
    setIsLoading(false);
  }

  if (!hydrated) {
    return (
      <main className="flex min-h-screen items-center justify-center bg-slate-950 text-white">
        <div className="animate-pulse text-slate-500">LoadingΓÇª</div>
      </main>
    );
  }

  return (
    <div className="flex h-screen bg-slate-950 text-white">
      <ChatSidebar
        conversations={conversations}
        activeId={activeId}
        isOpen={sidebarOpen}
        onSelect={(id) => {
          setActiveId(id);
          setInput("");
          setSidebarOpen(false);
        }}
        onNew={newConversation}
        onDelete={deleteConversation}
        onRename={async (id, title) => {
          try {
            await fetch(`/api/conversations/${encodeURIComponent(id)}`, {
              method: "PATCH",
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify({ title }),
            });
          } catch {
            // Ignore failures and still update locally.
          }
          setConversations((prev) =>
            prev.map((c) => (c.id === id ? { ...c, title, updatedAt: Date.now() } : c))
          );
        }}
        onToggle={() => setSidebarOpen((prev) => !prev)}
        onClose={() => setSidebarOpen(false)}
      />

      <main className="flex flex-1 flex-col" aria-label="Chat interface">
        <header className="flex flex-col gap-4 border-b border-slate-800 px-4 py-4 sm:px-6">
          <div className="flex items-center gap-3">
            <button
              type="button"
              onClick={() => setSidebarOpen(true)}
              className="shrink-0 sm:hidden"
              aria-label="Open sidebar"
            >
              <svg
                xmlns="http://www.w3.org/2000/svg"
                viewBox="0 0 24 24"
                fill="currentColor"
                className="h-6 w-6 text-slate-300"
              >
                <path
                  fillRule="evenodd"
                  d="M3 6.75A.75.75 0 0 1 3.75 6h16.5a.75.75 0 0 1 0 1.5H3.75A.75.75 0 0 1 3 6.75ZM3 12a.75.75 0 0 1 .75-.75h16.5a.75.75 0 0 1 0 1.5H3.75A.75.75 0 0 1 3 12Zm0 5.25a.75.75 0 0 1 .75-.75H12a.75.75 0 0 1 0 1.5H3.75a.75.75 0 0 1-.75-.75Z"
                  clipRule="evenodd"
                />
              </svg>
            </button>

            <div>
              <h1 className="text-lg font-semibold text-slate-200">
                {activeConversation?.title ?? "AI Chat"}
              </h1>
              <div className="flex items-center gap-2">
                <p className="text-sm text-slate-500">
                  Signed in as {user.name ?? user.email}
                </p>
                {(() => {
                  const displayAgent = AGENT_DEFINITIONS.find(
                    (agent) => agent.id === activeAgent
                  );
                  return (
                    <span className="inline-flex items-center gap-1 rounded-full border border-slate-700 bg-slate-900 px-2 py-0.5 text-xs text-slate-300">
                      <span aria-hidden="true">{displayAgent?.icon ?? "≡ƒñû"}</span>
                      {displayAgent?.name ?? "General Assistant"}
                      {routedAgent && (
                        <span className="text-[10px] uppercase tracking-wide text-emerald-400">
                          auto
                        </span>
                      )}
                    </span>
                  );
                })()}
              </div>
            </div>

            <div className="flex-1" />

            <button
              type="button"
              onClick={newConversation}
              className="hidden rounded-lg bg-blue-600 px-3 py-1.5 text-sm font-medium text-white transition hover:bg-blue-700 sm:inline-block"
            >
              + New chat
            </button>
          </div>
        </header>

        <ChatMessages messages={messages} isLoading={isLoading} />

        <div className="border-t border-slate-800 px-4 pb-4 pt-3 sm:px-6 sm:pb-6">
          <div className="mx-auto max-w-3xl">
            <AgentSelector value={activeAgent} onChange={handleAgentChange} />
            <ChatInput
              value={input}
              onChange={setInput}
              onSend={sendMessage}
              onStop={stopGenerating}
              onAttach={handleFileAttach}
              onVoiceToggle={toggleVoiceRecording}
              isLoading={isLoading}
              isUploading={isUploading}
              isRecording={isRecording}
              uploadingFileName={uploadingFileName ?? undefined}
              uploadStatus={uploadStatus ?? undefined}
              voiceStatus={voiceStatus ?? undefined}
              imagePreview={imagePreview}
              onRemoveImage={removeImage}
              disabled={isUploading}
            />
            <p className="mt-2 text-center text-[11px] text-slate-600">
              AI responses are generated by Google Gemini. Verify critical
              information.
            </p>
          </div>
        </div>
      </main>
    </div>
  );
}

"use client";

import { useRef, useEffect, useState, type ChangeEvent, type KeyboardEvent } from "react";
import Spinner from "@/components/ui/Spinner";

type ChatInputProps = {
  value: string;
  onChange: (value: string) => void;
  onSend: () => void;
  onStop?: () => void;
  onAttach?: (file: File) => void;
  onVoiceToggle?: () => void;
  isLoading: boolean;
  isUploading?: boolean;
  isRecording?: boolean;
  uploadingFileName?: string;
  uploadStatus?: string;
  voiceStatus?: string;
  imagePreview?: string | null;
  onRemoveImage?: () => void;
  disabled?: boolean;
};

/**
 * Auto-resizing textarea + Send button.
 * Enter sends, Shift+Enter inserts a newline.
 */
export default function ChatInput({
  value,
  onChange,
  onSend,
  onStop,
  onAttach,
  onVoiceToggle,
  isLoading,
  isUploading = false,
  isRecording = false,
  uploadingFileName,
  uploadStatus,
  voiceStatus,
  imagePreview,
  onRemoveImage,
  disabled = false,
}: ChatInputProps) {
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [focused, setFocused] = useState(false);

  // Auto-resize the textarea
  useEffect(() => {
    const el = textareaRef.current;
    if (!el) return;
    el.style.height = "auto";
    el.style.height = `${Math.min(el.scrollHeight, 200)}px`; // cap at 200px
  }, [value]);

  function handleKeyDown(e: KeyboardEvent<HTMLTextAreaElement>) {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      onSend();
    }
  }

  function handleFileChange(event: ChangeEvent<HTMLInputElement>) {
    const file = event.target.files?.[0];
    if (file && onAttach) {
      onAttach(file);
    }
    event.target.value = "";
  }

  const canSend =
    (!isLoading && !isUploading && !disabled && (value.trim().length > 0 || Boolean(imagePreview)));

  return (
    <div
      className={`relative flex items-end gap-3 rounded-2xl border bg-slate-800/60 px-4 py-3 transition focus-within:ring-2 focus-within:ring-blue-500/50 ${
        focused ? "border-blue-500/50" : "border-slate-700"
      }`}
    >
      <textarea
        ref={textareaRef}
        value={value}
        onChange={(e) => onChange(e.target.value)}
        onKeyDown={handleKeyDown}
        onFocus={() => setFocused(true)}
        onBlur={() => setFocused(false)}
        placeholder="Ask anything... Enter to send, Shift+Enter for newline"
        rows={1}
        autoFocus
        aria-multiline="true"
        aria-label="Chat message"
        disabled={isLoading || disabled}
        className="max-h-[200px] min-h-[24px] flex-1 resize-none bg-transparent text-[15px] text-slate-100 outline-none placeholder:text-slate-500 disabled:opacity-50"
      />

      <input
        ref={fileInputRef}
        type="file"
        accept=".pdf,.docx,.txt,.csv,image/*"
        className="hidden"
        onChange={handleFileChange}
      />

      {onVoiceToggle ? (
        <button
          type="button"
          onClick={onVoiceToggle}
          disabled={isLoading || disabled || isUploading}
          className={`flex h-10 w-10 shrink-0 items-center justify-center rounded-xl transition ${
            isRecording
              ? "bg-red-600 text-white hover:bg-red-700"
              : "bg-slate-700 text-slate-200 hover:bg-slate-600"
          } disabled:cursor-not-allowed disabled:bg-slate-700/50 disabled:text-slate-500`}
          aria-label={isRecording ? "Stop voice recording" : "Start voice recording"}
        >
          <svg
            xmlns="http://www.w3.org/2000/svg"
            viewBox="0 0 24 24"
            fill="currentColor"
            className="h-5 w-5"
          >
            <path d="M12 14.25a3.75 3.75 0 0 0 3.75-3.75V5.25A3.75 3.75 0 0 0 8.25 5.25v5.25A3.75 3.75 0 0 0 12 14.25Zm-6.75 0A.75.75 0 0 0 4.5 15v.75a6.75 6.75 0 0 0 13.5 0V15a.75.75 0 0 0-1.5 0v.75a5.25 5.25 0 0 1-10.5 0V15a.75.75 0 0 0-.75-.75Zm6.75-10.5A2.25 2.25 0 0 1 14.25 5.25v5.25a2.25 2.25 0 0 1-4.5 0V5.25A2.25 2.25 0 0 1 12 3.75Z" />
          </svg>
        </button>
      ) : null}

      <button
        type="button"
        onClick={() => fileInputRef.current?.click()}
        disabled={isLoading || disabled || isUploading}
        className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-slate-700 text-slate-200 transition hover:bg-slate-600 disabled:cursor-not-allowed disabled:bg-slate-700/50 disabled:text-slate-500"
        aria-label="Attach file or image"
      >
        <svg
          xmlns="http://www.w3.org/2000/svg"
          viewBox="0 0 24 24"
          fill="currentColor"
          className="h-5 w-5"
        >
          <path d="M16.5 6.75a2.25 2.25 0 0 1 4.5 0v9.75a5.25 5.25 0 0 1-10.5 0V8.25a.75.75 0 0 1 1.5 0v8.25a3.75 3.75 0 0 0 7.5 0V6.75a.75.75 0 0 0-1.5 0v8.25a2.25 2.25 0 1 1-4.5 0V6.75Z" />
        </svg>
      </button>

      {isLoading && onStop ? (
        <button
          type="button"
          onClick={onStop}
          className="flex h-10 shrink-0 items-center justify-center rounded-xl bg-red-600 px-4 text-sm font-medium text-white transition hover:bg-red-700"
          aria-label="Stop generating"
        >
          Stop
        </button>
      ) : null}

      <button
        type="button"
        onClick={onSend}
        disabled={!canSend}
        className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-blue-600 text-white transition hover:bg-blue-700 disabled:cursor-not-allowed disabled:opacity-40"
        aria-label="Send message"
      >
        {isLoading ? (
          <Spinner className="h-5 w-5" label="Sending" />
        ) : (
          /* Arrow-up icon */
          <svg
            xmlns="http://www.w3.org/2000/svg"
            viewBox="0 0 24 24"
            fill="currentColor"
            className="h-5 w-5"
          >
            <path d="M3.478 2.404a.75.75 0 0 0-.926.941l2.432 7.905H13.5a.75.75 0 0 1 0 1.5H4.984l-2.432 7.905a.75.75 0 0 0 .926.94 60.519 60.519 0 0 0 18.445-8.986.75.75 0 0 0 0-1.218A60.517 60.517 0 0 0 3.478 2.404Z" />
          </svg>
        )}
      </button>

      {imagePreview ? (
        <div className="absolute inset-x-4 top-[-3.75rem] z-10 flex items-center justify-between rounded-2xl border border-slate-700 bg-slate-900/95 px-3 py-2 shadow-xl">
          <div className="flex items-center gap-2">
            <img src={imagePreview} alt="Selected preview" className="h-10 w-10 rounded-lg object-cover" />
            <span className="text-sm text-slate-200">Image ready</span>
          </div>
          <button
            type="button"
            onClick={onRemoveImage}
            className="rounded-full bg-slate-800 px-2 py-1 text-xs text-slate-300 hover:bg-slate-700"
            aria-label="Remove image"
          >
            Remove
          </button>
        </div>
      ) : null}

      {(isUploading || uploadingFileName || uploadStatus || voiceStatus) && (
        <div className="absolute left-0 right-0 top-full z-10 mt-2 rounded-2xl bg-slate-900/95 px-4 py-3 text-xs text-slate-300 shadow-xl sm:px-5">
          {uploadingFileName ? (
            <div className="font-semibold text-slate-100">{uploadingFileName}</div>
          ) : null}
          {uploadStatus ? <div className="mt-1">{uploadStatus}</div> : null}
          {voiceStatus ? <div className="mt-1">{voiceStatus}</div> : null}
        </div>
      )}
    </div>
  );
}

"use client";

import { useRef, useEffect } from "react";
import type { ChatMessage } from "@/app/types/chat";
import ChatBubble from "./ChatBubble";
import TypingBubble from "./TypingBubble";

type ChatMessagesProps = {
  messages: ChatMessage[];
  isLoading: boolean;
};

/**
 * Scrollable message list with auto-scroll to the newest message.
 * Shows a typing indicator while the API is loading.
 */
export default function ChatMessages({
  messages,
  isLoading,
}: ChatMessagesProps) {
  const bottomRef = useRef<HTMLDivElement>(null);

  // Auto-scroll whenever messages change or loading state changes
  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages, isLoading]);

  return (
    <div
      className="flex-1 overflow-y-auto px-4 py-6 sm:px-6"
      role="log"
      aria-live="polite"
      aria-busy={isLoading}
    >
      {messages.length === 0 ? (
        <div className="flex h-full flex-col items-center justify-center text-center">
          <div className="mb-4 text-5xl">≡ƒñû</div>
          <h2 className="text-xl font-semibold text-slate-200">
            How can I help you today?
          </h2>
          <p className="mt-2 max-w-md text-sm text-slate-500">
            Ask any question ΓÇö I'll do my best to answer with the help of
            Gemini AI.
          </p>
        </div>
      ) : (
        <div className="mx-auto flex max-w-3xl flex-col gap-4">
          {messages.map((msg) => (
            <ChatBubble
              key={msg.id}
              role={msg.role}
              message={msg.message}
              createdAt={msg.createdAt}
              isError={msg.isError}
              usedToolId={msg.usedToolId}
              usedToolLabel={msg.usedToolLabel}
              agents={msg.agents}
              agentNames={msg.agentNames}
              agentIcons={msg.agentIcons}
              usedToolIds={msg.usedToolIds}
              usedToolLabels={msg.usedToolLabels}
            />
          ))}

          {/* Typing indicator */}
          {isLoading && <TypingBubble />}
        </div>
      )}

      {/* Invisible anchor for auto-scroll */}
      <div ref={bottomRef} />
    </div>
  );
}

