"use client";

import { useEffect, useMemo, useState } from "react";

type KnowledgeEntry = {
  id: string;
  title: string;
  content: string;
  category: string;
  source: string;
  tags: string[];
  fileName?: string | null;
  fileType?: string | null;
  createdAt: string;
  updatedAt: string;
};

type KnowledgeManagerProps = {
  user: {
    id: string;
    name?: string | null;
    email?: string | null;
  };
};

const CATEGORIES = [
  "Government schemes",
  "Education",
  "Healthcare",
  "Agriculture",
  "Economy",
  "Startups",
  "Laws and policies",
  "Other",
];

export default function KnowledgeManager({ user }: KnowledgeManagerProps) {
  const [entries, setEntries] = useState<KnowledgeEntry[]>([]);
  const [search, setSearch] = useState("");
  const [title, setTitle] = useState("");
  const [category, setCategory] = useState(CATEGORIES[0]);
  const [source, setSource] = useState("");
  const [tags, setTags] = useState("");
  const [content, setContent] = useState("");
  const [file, setFile] = useState<File | null>(null);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState<string | null>(null);

  async function refreshEntries() {
    const res = await fetch(`/api/knowledge?search=${encodeURIComponent(search)}`);
    const data = await res.json();
    setEntries(data.entries ?? []);
  }

  useEffect(() => {
    void refreshEntries();
  }, [search]);

  async function handleSubmit(event: React.FormEvent) {
    event.preventDefault();
    setLoading(true);
    setMessage(null);

    const formData = new FormData();
    formData.append("title", title);
    formData.append("category", category);
    formData.append("source", source);
    formData.append("tags", tags);
    formData.append("content", content);
    if (file) formData.append("file", file);
    if (editingId) formData.append("id", editingId);

    const res = await fetch("/api/knowledge", {
      method: editingId ? "PUT" : "POST",
      body: formData,
    });
    const data = await res.json();
    setLoading(false);
    if (data.success) {
      setMessage(editingId ? "Knowledge updated." : "Knowledge imported.");
      setTitle("");
      setCategory(CATEGORIES[0]);
      setSource("");
      setTags("");
      setContent("");
      setFile(null);
      setEditingId(null);
      await refreshEntries();
    } else {
      setMessage(data.error || "Unable to save knowledge entry.");
    }
  }

  async function handleDelete(id: string) {
    const res = await fetch(`/api/knowledge?id=${id}`, { method: "DELETE" });
    const data = await res.json();
    if (data.success) {
      await refreshEntries();
    }
  }

  function startEdit(entry: KnowledgeEntry) {
    setEditingId(entry.id);
    setTitle(entry.title);
    setCategory(entry.category || CATEGORIES[0]);
    setSource(entry.source);
    setTags(entry.tags.join(", "));
    setContent(entry.content);
    setFile(null);
  }

  const filteredEntries = useMemo(() => {
    if (!search.trim()) return entries;
    const term = search.toLowerCase();
    return entries.filter((entry) =>
      [entry.title, entry.category, entry.source, entry.content, entry.tags.join(" ")]
        .join(" ")
        .toLowerCase()
        .includes(term)
    );
  }, [entries, search]);

  return (
    <main className="min-h-screen bg-slate-950 px-4 py-8 text-slate-100 sm:px-6 lg:px-8">
      <div className="mx-auto flex max-w-7xl flex-col gap-8">
        <header className="rounded-2xl border border-slate-800 bg-slate-900/80 p-6 shadow-xl">
          <p className="text-sm uppercase tracking-[0.3em] text-blue-400">Knowledge Management</p>
          <h1 className="mt-3 text-3xl font-semibold">India Digital Brain knowledge sources</h1>
          <p className="mt-2 max-w-2xl text-sm text-slate-400">
            Import documents, curate knowledge, and manage sources that power RAG responses for Indian public services and policy topics.
          </p>
          <p className="mt-3 text-sm text-slate-500">Signed in as {user.name ?? user.email}</p>
        </header>

        <form onSubmit={handleSubmit} className="rounded-2xl border border-slate-800 bg-slate-900/80 p-6 shadow-xl">
          <div className="grid gap-4 md:grid-cols-2">
            <label className="flex flex-col gap-2 text-sm">
              <span>Title</span>
              <input value={title} onChange={(e) => setTitle(e.target.value)} className="rounded-lg border border-slate-700 bg-slate-950 px-3 py-2" required />
            </label>
            <label className="flex flex-col gap-2 text-sm">
              <span>Category</span>
              <select value={category} onChange={(e) => setCategory(e.target.value)} className="rounded-lg border border-slate-700 bg-slate-950 px-3 py-2">
                {CATEGORIES.map((item) => (
                  <option key={item} value={item}>
                    {item}
                  </option>
                ))}
              </select>
            </label>
            <label className="flex flex-col gap-2 text-sm">
              <span>Source</span>
              <input value={source} onChange={(e) => setSource(e.target.value)} className="rounded-lg border border-slate-700 bg-slate-950 px-3 py-2" required />
            </label>
            <label className="flex flex-col gap-2 text-sm">
              <span>Tags</span>
              <input value={tags} onChange={(e) => setTags(e.target.value)} className="rounded-lg border border-slate-700 bg-slate-950 px-3 py-2" placeholder="policy, health, finance" />
            </label>
          </div>

          <label className="mt-4 flex flex-col gap-2 text-sm">
            <span>Content</span>
            <textarea value={content} onChange={(e) => setContent(e.target.value)} rows={6} className="rounded-lg border border-slate-700 bg-slate-950 px-3 py-2" placeholder="Paste or edit knowledge content" />
          </label>

          <label className="mt-4 flex flex-col gap-2 text-sm">
            <span>Import document (PDF, DOCX, TXT, CSV, Markdown)</span>
            <input type="file" accept=".pdf,.docx,.txt,.csv,.md,.markdown" onChange={(e) => setFile(e.target.files?.[0] ?? null)} className="rounded-lg border border-slate-700 bg-slate-950 px-3 py-2" />
          </label>

          <div className="mt-5 flex flex-wrap items-center gap-3">
            <button type="submit" disabled={loading} className="rounded-lg bg-blue-600 px-4 py-2 text-sm font-medium text-white disabled:opacity-60">
              {loading ? "Saving..." : editingId ? "Update knowledge" : "Import knowledge"}
            </button>
            {editingId ? <button type="button" onClick={() => { setEditingId(null); setTitle(""); setCategory(CATEGORIES[0]); setSource(""); setTags(""); setContent(""); setFile(null); }} className="rounded-lg border border-slate-700 px-4 py-2 text-sm">Cancel</button> : null}
          </div>
          {message ? <p className="mt-3 text-sm text-slate-300">{message}</p> : null}
        </form>

        <section className="rounded-2xl border border-slate-800 bg-slate-900/80 p-6 shadow-xl">
          <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
            <div>
              <h2 className="text-xl font-semibold">Knowledge sources</h2>
              <p className="text-sm text-slate-400">Search, update, or remove imported knowledge entries.</p>
            </div>
            <input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Search knowledge" className="w-full rounded-lg border border-slate-700 bg-slate-950 px-3 py-2 sm:w-72" />
          </div>

          <div className="mt-6 overflow-x-auto">
            <table className="min-w-full divide-y divide-slate-800 text-sm">
              <thead>
                <tr className="text-left text-slate-400">
                  <th className="px-3 py-2">Title</th>
                  <th className="px-3 py-2">Category</th>
                  <th className="px-3 py-2">Source</th>
                  <th className="px-3 py-2">Tags</th>
                  <th className="px-3 py-2">Updated</th>
                  <th className="px-3 py-2">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-800">
                {filteredEntries.map((entry) => (
                  <tr key={entry.id} className="align-top text-slate-300">
                    <td className="px-3 py-3">
                      <div className="font-medium text-slate-100">{entry.title}</div>
                      <div className="mt-1 max-w-xl text-xs text-slate-500 line-clamp-3">{entry.content}</div>
                    </td>
                    <td className="px-3 py-3">{entry.category}</td>
                    <td className="px-3 py-3">{entry.source}</td>
                    <td className="px-3 py-3">{entry.tags.join(", ")}</td>
                    <td className="px-3 py-3">{new Date(entry.updatedAt).toLocaleDateString()}</td>
                    <td className="px-3 py-3">
                      <div className="flex gap-2">
                        <button type="button" onClick={() => startEdit(entry)} className="rounded bg-slate-800 px-2 py-1 text-xs">Edit</button>
                        <button type="button" onClick={() => void handleDelete(entry.id)} className="rounded bg-red-600/80 px-2 py-1 text-xs">Delete</button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </section>
      </div>
    </main>
  );
}

import type { NextAuthOptions } from "next-auth";
import CredentialsProvider from "next-auth/providers/credentials";
import GoogleProvider from "next-auth/providers/google";
import { compare, hash } from "bcryptjs";
import { prisma } from "@/lib/prisma";

// Validate required env vars for authentication
const _requiredEnvs = [
  "NEXTAUTH_SECRET",
  "NEXTAUTH_URL",
  "DATABASE_URL",
  "GOOGLE_CLIENT_ID",
  "GOOGLE_CLIENT_SECRET",
];
const _missing = _requiredEnvs.filter((k) => !process.env[k]);
if (_missing.length > 0) {
  // Warn rather than throw so local dev/builds don't break unexpectedly,
  // but surface a clear hint for the common JWT decryption failure.
  // If you see "decryption operation failed", set `NEXTAUTH_SECRET`.
  // Example: `NEXTAUTH_SECRET=$(node -e "console.log(require('crypto').randomBytes(32).toString('hex'))")`
  // and set `NEXTAUTH_URL` to your app origin (e.g. http://localhost:3000).
  // Keep secrets out of source control (use .env.local or your hosting provider).
  // eslint-disable-next-line no-console
  console.warn("[auth] Missing environment variables:", _missing.join(", "));
}

async function findUserByEmail(email: string) {
  return prisma.user.findUnique({
    where: { email: email.toLowerCase().trim() },
  });
}

export const authOptions: NextAuthOptions = {
  providers: [
    GoogleProvider({
      clientId: process.env.GOOGLE_CLIENT_ID ?? "",
      clientSecret: process.env.GOOGLE_CLIENT_SECRET ?? "",
    }),
    CredentialsProvider({
      id: "credentials",
      name: "Email",
      credentials: {
        email: { label: "Email", type: "email", placeholder: "you@example.com" },
        password: { label: "Password", type: "password" },
      },
      authorize: async (credentials) => {
        if (!credentials?.email || !credentials.password) {
          return null;
        }

        const user = await findUserByEmail(credentials.email);
        if (!user) return null;

        const validPassword = await compare(credentials.password, user.password);
        if (!validPassword) return null;

        return { id: user.id, email: user.email, name: user.name };
      },
    }),
  ],
  pages: {
    signIn: "/login",
    newUser: "/register",
  },
  session: {
    strategy: "jwt",
    maxAge: 30 * 24 * 60 * 60,
  },
  jwt: {
    // Explicitly provide the secret and enable encryption to ensure tokens
    // are handled consistently across environments.
    secret: process.env.NEXTAUTH_SECRET ?? undefined,
  },
  callbacks: {
    async jwt({ token, user, profile }) {
      if (user?.email) {
        const foundUser = await findUserByEmail(user.email);
        if (foundUser) {
          token.id = foundUser.id;
          token.email = foundUser.email;
          token.name = foundUser.name;
        } else {
          token.id = user.id as string;
          token.email = user.email;
          token.name = user.name;
        }
      } else if (!token.id && profile?.email) {
        const foundUser = await findUserByEmail(profile.email);
        if (foundUser) {
          token.id = foundUser.id;
          token.email = foundUser.email;
          token.name = foundUser.name;
        }
      }
      return token;
    },
    async session({ session, token }) {
      if (session.user) {
        session.user.id = token.id as string;
        session.user.email = token.email as string;
        session.user.name = token.name as string;
      }
      return session;
    },
    async signIn({ account, profile }) {
      if (account?.provider === "google" && profile?.email) {
        const email = profile.email.toLowerCase();
        const existingUser = await findUserByEmail(email);
        if (!existingUser) {
          const placeholderPassword = await hash(crypto.randomUUID(), 12);
          await prisma.user.create({
            data: {
              email,
              name: profile.name ?? email.split("@")[0],
              password: placeholderPassword,
            },
          });
        }
      }

      return true;
    },
  },
  // Top-level secret used for signing/encrypting NextAuth tokens and cookies.
  // Must be a stable, strong value across deployments.
  secret: process.env.NEXTAUTH_SECRET,
  debug: process.env.NODE_ENV === "development",
};

import fs from "fs/promises";
import path from "path";
import os from "os";
import mammoth from "mammoth";
import { PDFParse } from "pdf-parse";
import { parse } from "csv-parse/sync";

const MAX_EXTRACTED_TEXT_LENGTH = 20000;

function sanitizeFileName(name: string) {
  return name.replace(/[^a-zA-Z0-9._-]/g, "_").replace(/_+/g, "_");
}

export function getUploadDirectory(userId: string) {
  return path.join(os.tmpdir(), "digital-brain-india-uploads", userId);
}

export async function saveUploadedFile(userId: string, fileName: string, data: Uint8Array) {
  const uploadDir = getUploadDirectory(userId);
  await fs.mkdir(uploadDir, { recursive: true });
  const safeName = `${Date.now()}-${sanitizeFileName(fileName)}`;
  const filePath = path.join(uploadDir, safeName);
  await fs.writeFile(filePath, data);
  return filePath;
}

function truncateText(text: string) {
  if (text.length <= MAX_EXTRACTED_TEXT_LENGTH) return text;
  return `${text.slice(0, MAX_EXTRACTED_TEXT_LENGTH)}\n\n[Truncated file content]`;
}

export async function extractTextFromBuffer(
  buffer: Buffer,
  fileName: string,
  mimeType: string
) {
  const lowerName = fileName.toLowerCase();
  if (lowerName.endsWith(".pdf")) {
    const parseResult = await new PDFParse(buffer).getText();
    return truncateText(parseResult.text || "");
  }

  if (lowerName.endsWith(".docx")) {
    const result = await mammoth.extractRawText({ buffer });
    return truncateText(result.value || "");
  }

  if (lowerName.endsWith(".csv")) {
    const text = buffer.toString("utf-8");
    const rows = parse(text, {
      relax_column_count: true,
      skip_empty_lines: true,
    }) as Array<Array<unknown>>;
    const formatted = rows
      .map((row) => row.map((cell) => String(cell ?? "")).join(", "))
      .join("\n");
    return truncateText(formatted);
  }

  if (lowerName.endsWith(".txt")) {
    return truncateText(buffer.toString("utf-8"));
  }

  throw new Error("Unsupported file type");
}

import { prisma } from "@/lib/prisma";
import { ingestParsedDocument } from "./ingest";
import { loadKnowledgeFromDirectory } from "./loader";
import { logError, logEvent } from "@/lib/logger";
import type { KnowledgeContentType, ParsedDocument } from "./types";

/**
 * Background ingestion job service (Phase 9).
 *
 * Provides queued ingestion with progress tracking, per-document status,
 * retry support, and ingestion logs. Jobs are persisted in the IngestionJob
 * table and processed sequentially.
 */

export type JobType = "bulk" | "upload" | "reindex" | "reingest";
export type JobStatus = "queued" | "running" | "completed" | "failed";
export type JobItemStatus = "pending" | "processing" | "completed" | "failed" | "skipped";

/** Creates a new queued ingestion job. */
export async function createIngestionJob(
  type: JobType,
  documentIds: string[] = []
): Promise<string> {
  const job = await prisma.ingestionJob.create({
    data: {
      type,
      status: "queued",
      totalItems: documentIds.length,
      documents: documentIds.length > 0
        ? {
            create: documentIds.map((documentId) => ({
              documentId,
              status: "pending" as JobItemStatus,
            })),
          }
        : undefined,
    },
  });

  logEvent("info", "Ingestion job created", { jobId: job.id, type, items: documentIds.length });
  return job.id;
}

/** Marks a job as running and records the start time. */
export async function startJob(jobId: string): Promise<void> {
  await prisma.ingestionJob.update({
    where: { id: jobId },
    data: { status: "running", startedAt: new Date() },
  });
}

/** Marks a job as completed with final counts. */
export async function completeJob(jobId: string): Promise<void> {
  await prisma.ingestionJob.update({
    where: { id: jobId },
    data: { status: "completed", progress: 100, completedAt: new Date() },
  });
}

/** Marks a job as failed with an error message. */
export async function failJob(jobId: string, error: string): Promise<void> {
  await prisma.ingestionJob.update({
    where: { id: jobId },
    data: { status: "failed", error, completedAt: new Date() },
  });
}

/** Updates job progress counters. */
export async function updateJobProgress(
  jobId: string,
  delta: { processed?: number; succeeded?: number; failed?: number }
): Promise<void> {
  const job = await prisma.ingestionJob.findUnique({ where: { id: jobId } });
  if (!job) return;

  const processed = job.processedItems + (delta.processed ?? 0);
  const succeeded = job.succeededItems + (delta.succeeded ?? 0);
  const failed = job.failedItems + (delta.failed ?? 0);
  const progress = job.totalItems > 0 ? Math.round((processed / job.totalItems) * 100) : 100;

  await prisma.ingestionJob.update({
    where: { id: jobId },
    data: { processedItems: processed, succeededItems: succeeded, failedItems: failed, progress },
  });
}

/** Updates a single job-document item status. */
export async function updateJobItemStatus(
  jobId: string,
  documentId: string,
  status: JobItemStatus,
  error?: string
): Promise<void> {
  await prisma.ingestionJobDocument.updateMany({
    where: { jobId, documentId },
    data: {
      status,
      error: error ?? null,
      completedAt: status === "completed" || status === "failed" ? new Date() : null,
    },
  });
}

/** Adds a log line to a job. */
export async function addJobLog(
  jobId: string,
  level: "info" | "warn" | "error",
  message: string,
  documentId?: string
): Promise<void> {
  await prisma.ingestionLog.create({
    data: { jobId, level, message, documentId },
  });
}

/** Fetches a job with its logs and document items. */
export async function getJob(jobId: string) {
  return prisma.ingestionJob.findUnique({
    where: { id: jobId },
    include: {
      logs: { orderBy: { createdAt: "asc" } },
      documents: {
        include: { document: { select: { id: true, title: true } } },
        orderBy: { createdAt: "asc" },
      },
    },
  });
}

/** Lists recent jobs, newest first. */
export async function listJobs(limit = 20) {
  return prisma.ingestionJob.findMany({
    orderBy: { createdAt: "desc" },
    take: limit,
    include: {
      _count: { select: { documents: true, logs: true } },
    },
  });
}

/** Retries failed documents in a job by re-queuing them. */
export async function retryFailedDocuments(jobId: string): Promise<number> {
  const failed = await prisma.ingestionJobDocument.findMany({
    where: { jobId, status: "failed" },
    select: { documentId: true },
  });

  if (failed.length === 0) return 0;

  await prisma.ingestionJobDocument.updateMany({
    where: { jobId, status: "failed" },
    data: { status: "pending", error: null, completedAt: null },
  });

  await prisma.ingestionJob.update({
    where: { id: jobId },
    data: { status: "queued", failedItems: 0, processedItems: 0, progress: 0 },
  });

  logEvent("info", "Retrying failed documents", { jobId, count: failed.length });
  return failed.length;
}

/** Processes a bulk ingestion job (directory scan). */
export async function processBulkJob(jobId: string, rootDir: string): Promise<void> {
  await startJob(jobId);
  await addJobLog(jobId, "info", `Starting bulk ingestion from ${rootDir}`);

  try {
    const documents = await loadKnowledgeFromDirectory(rootDir);
    await prisma.ingestionJob.update({
      where: { id: jobId },
      data: { totalItems: documents.length },
    });

    for (const document of documents) {
      const outcome = await ingestParsedDocument(document);
      await updateJobItemStatus(jobId, document.path ?? "", outcome === "failed" ? "failed" : outcome === "skipped" ? "skipped" : "completed");
      await updateJobProgress(jobId, {
        processed: 1,
        succeeded: outcome === "created" || outcome === "updated" ? 1 : 0,
        failed: outcome === "failed" ? 1 : 0,
      });
      await addJobLog(
        jobId,
        outcome === "failed" ? "error" : "info",
        `${document.metadata.title}: ${outcome}`,
        document.path ?? undefined
      );
    }

    await completeJob(jobId);
    await addJobLog(jobId, "info", "Bulk ingestion completed");
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    await failJob(jobId, message);
    await addJobLog(jobId, "error", `Bulk ingestion failed: ${message}`);
  }
}

/** Processes a re-ingest job (re-scan the corpus directory). */
export async function processReingestJob(jobId: string, rootDir: string): Promise<void> {
  await processBulkJob(jobId, rootDir);
}

/** Processes a single-document re-index job. */
export async function processReindexJob(jobId: string, documentId: string): Promise<void> {
  await startJob(jobId);
  await addJobLog(jobId, "info", `Re-indexing document ${documentId}`);

  try {
    const document = await prisma.knowledgeDocument.findUnique({
      where: { id: documentId },
      select: { id: true, title: true, content: true, contentType: true },
    });

    if (!document) {
      throw new Error(`Document ${documentId} not found`);
    }

    // Re-ingest the document content (re-splits and re-embeds).
    const parsed: ParsedDocument = {
      path: null,
      fileName: document.title,
      rawContent: document.content,
      metadata: {
        title: document.title,
        category: "governance",
        language: "en",
        source: "Re-index",
        tags: [],
      },
      content: document.content,
      contentType: document.contentType as KnowledgeContentType,
    };

    const outcome = await ingestParsedDocument(parsed);
    await updateJobItemStatus(jobId, documentId, outcome === "failed" ? "failed" : "completed");
    await updateJobProgress(jobId, { processed: 1, succeeded: outcome === "failed" ? 0 : 1, failed: outcome === "failed" ? 1 : 0 });
    await addJobLog(jobId, outcome === "failed" ? "error" : "info", `Re-index ${document.title}: ${outcome}`, documentId);

    if (outcome === "failed") {
      await failJob(jobId, `Re-index failed for ${document.title}`);
    } else {
      await completeJob(jobId);
    }
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    await failJob(jobId, message);
    await addJobLog(jobId, "error", `Re-index failed: ${message}`, documentId);
  }
}

import type { Chunk } from "./types";

/**
 * Configuration for the document splitter.
 */
export interface SplitOptions {
  /** Target chunk size in characters. Defaults to 500. */
  chunkSize?: number;
  /** Number of characters to overlap between consecutive chunks. Defaults to 100. */
  overlap?: number;
  /** When true (default), chunk boundaries prefer paragraph boundaries. */
  preserveParagraphs?: boolean;
  /** When true (default), markdown headings are preserved as heading metadata. */
  preserveHeadings?: boolean;
  /** When true (default), markdown tables are kept together in a single chunk. */
  keepTablesTogether?: boolean;
}

const DEFAULT_CHUNK_SIZE = 500;
const DEFAULT_OVERLAP = 100;

/**
 * Splits a document into size-bounded chunks while preserving:
 *   - Paragraph structure (when preserveParagraphs is true)
 *   - Markdown heading hierarchy (when preserveHeadings is true)
 *   - Markdown tables (when keepTablesTogether is true)
 *
 * Algorithm:
 *   1. Normalize whitespace (collapse runs of blank lines).
 *   2. Split into paragraph units (lines separated by blank lines).
 *   3. Track the current heading hierarchy as headings are encountered.
 *   4. Keep markdown tables together as a single unit.
 *   5. Break any paragraph longer than `chunkSize` into sub-units sized
 *      `chunkSize` with `overlap`.
 *   6. Greedily merge consecutive units into chunks up to `chunkSize`.
 *   7. Carry the tail of the previous chunk into the next one as overlap.
 *
 * Fully typed, side-effect free, and reusable by any ingestion pipeline.
 *
 * @returns An array of Chunk rows (never null; empty for blank input).
 */
export function splitDocument(content: string, options: SplitOptions = {}): Chunk[] {
  const {
    chunkSize,
    overlap,
    preserveParagraphs = true,
    preserveHeadings = true,
    keepTablesTogether = true,
  } = options;

  const safeChunkSize = resolveChunkSize(chunkSize);
  const safeOverlap = resolveOverlap(overlap, safeChunkSize);

  const normalized = normalizeWhitespace(content);
  if (!normalized) return [];

  // Split into paragraph units, then break oversized units further.
  const units = preserveParagraphs ? splitParagraphs(normalized) : [normalized];
  const boundedUnits = units.flatMap((unit) => boundUnit(unit, safeChunkSize, safeOverlap));

  // Build chunks with heading hierarchy tracking.
  return buildChunks(boundedUnits, safeChunkSize, safeOverlap, {
    preserveHeadings,
    keepTablesTogether,
  });
}

/** Fall back to defaults when chunkSize is invalid (<= 0 or not finite). */
function resolveChunkSize(chunkSize: number | undefined): number {
  if (typeof chunkSize !== "number" || !Number.isFinite(chunkSize) || chunkSize <= 0) {
    return DEFAULT_CHUNK_SIZE;
  }
  return Math.floor(chunkSize);
}

/** Clamp overlap so it is never >= chunkSize and never negative. */
function resolveOverlap(overlap: number | undefined, chunkSize: number): number {
  if (typeof overlap !== "number" || !Number.isFinite(overlap) || overlap <= 0) {
    return DEFAULT_OVERLAP < chunkSize ? DEFAULT_OVERLAP : Math.floor(chunkSize / 2);
  }
  return Math.min(Math.floor(overlap), Math.max(0, chunkSize - 1));
}

/** Collapses blank-line runs and trims leading/trailing whitespace. */
function normalizeWhitespace(content: string): string {
  return content
    .replace(/\r\n?/g, "\n")
    .replace(/[ \t]+\n/g, "\n")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

/** Splits normalized text into paragraphs separated by blank lines. */
function splitParagraphs(content: string): string[] {
  return content
    .split(/\n\s*\n/)
    .map((paragraph) => paragraph.trim())
    .filter(Boolean);
}

/**
 * If a paragraph exceeds chunkSize, break it at word boundaries into
 * sub-units no larger than chunkSize, carrying overlap between them.
 */
function boundUnit(unit: string, chunkSize: number, overlap: number): string[] {
  if (unit.length <= chunkSize) return [unit];
  return splitLongText(unit, chunkSize, overlap);
}

/** Word-boundary subdivision of text longer than chunkSize. */
function splitLongText(text: string, chunkSize: number, overlap: number): string[] {
  const words = text.split(/\s+/);
  const parts: string[] = [];
  let buffer: string[] = [];
  let bufferLength = 0;

  const flush = () => {
    if (buffer.length === 0) return;
    let joined = buffer.join(" ");
    if (parts.length > 0 && overlap > 0) {
      const previous = parts[parts.length - 1];
      joined = `${previous.slice(-overlap)} ${joined}`;
    }
    parts.push(joined.trim());
    buffer = [];
    bufferLength = 0;
  };

  for (const word of words) {
    const nextLength = bufferLength + (bufferLength > 0 ? 1 : 0) + word.length;
    if (nextLength > chunkSize && buffer.length > 0) {
      flush();
    }
    buffer.push(word);
    bufferLength += word.length + (bufferLength > 0 ? 1 : 0);
  }
  flush();

  return parts;
}

/** Options for the chunk-building phase. */
interface BuildChunkOptions {
  preserveHeadings: boolean;
  keepTablesTogether: boolean;
}

/** Heading detection result. */
interface HeadingInfo {
  /** Full heading hierarchy path. */
  path: string[];
  /** The immediate heading text. */
  heading: string;
}

/**
 * Detects a markdown heading line and returns its hierarchy.
 * Returns null when the unit is not a heading.
 */
function detectHeading(unit: string): HeadingInfo | null {
  const match = unit.match(/^(#{1,6})\s+(.+)$/);
  if (!match) return null;
  const level = match[1].length;
  const heading = match[2].trim();
  return { path: [heading], heading };
}

/**
 * Detects whether a unit looks like a markdown table.
 * A table has a header row, a separator row of dashes, and at least one body row.
 */
function looksLikeTable(unit: string): boolean {
  const lines = unit.split("\n").map((line) => line.trim()).filter(Boolean);
  if (lines.length < 3) return false;
  // The second line must be a separator row like | --- | --- |
  const separator = lines[1];
  if (!separator.startsWith("|") && !separator.startsWith("|-")) return false;
  return /^\|?[\s:|-]+\|?$/.test(separator) && separator.includes("-");
}

/**
 * Greedily merges paragraph units into chunks no larger than chunkSize,
 * tracking heading hierarchy and table boundaries as it goes.
 */
function buildChunks(
  units: string[],
  chunkSize: number,
  overlap: number,
  options: BuildChunkOptions
): Chunk[] {
  const chunks: Chunk[] = [];
  let current: string[] = [];
  let currentLength = 0;
  let currentHeadingPath: string[] = [];
  let currentHeading: string | null = null;
  let currentHasTable = false;

  const pushChunk = (
    text: string,
    headingPath: string[],
    heading: string | null,
    hasTable: boolean
  ) => {
    const clean = text.trim();
    if (!clean) return;
    chunks.push({
      index: chunks.length,
      content: clean,
      headingPath,
      heading,
      hasTable,
    });
  };

  for (const unit of units) {
    // Detect heading lines and update the hierarchy.
    const headingInfo = options.preserveHeadings ? detectHeading(unit) : null;
    if (headingInfo) {
      // Flush the current chunk before starting a new heading section.
      if (current.length > 0) {
        const merged = mergeUnitsText(current);
        if (merged) pushChunk(merged, currentHeadingPath, currentHeading, currentHasTable);
        current = [];
        currentLength = 0;
        currentHasTable = false;
      }
      currentHeadingPath = headingInfo.path;
      currentHeading = headingInfo.heading;
      continue;
    }

    // Detect tables and keep them together when requested.
    const isTable = options.keepTablesTogether && looksLikeTable(unit);
    if (isTable) {
      // Flush the current chunk so the table stays together.
      if (current.length > 0) {
        const merged = mergeUnitsText(current);
        if (merged) pushChunk(merged, currentHeadingPath, currentHeading, currentHasTable);
        current = [];
        currentLength = 0;
      }
      // If the table fits in a chunk, emit it as its own chunk.
      if (unit.length <= chunkSize) {
        pushChunk(unit, currentHeadingPath, currentHeading, true);
        continue;
      }
      // Oversized table: fall through to normal merging with hasTable=true.
      currentHasTable = true;
    }

    const separatorLength = current.length > 0 ? 2 : 0; // "\n\n"
    const nextLength = currentLength + separatorLength + unit.length;

    if (nextLength <= chunkSize) {
      current.push(unit);
      currentLength += separatorLength + unit.length;
      continue;
    }

    // Flush the accumulated unit(s) as a chunk.
    const merged = mergeUnitsText(current);
    if (merged) pushChunk(merged, currentHeadingPath, currentHeading, currentHasTable);

    // Start the next chunk; carry the tail overlap, if any.
    current = overlap > 0 && merged ? [overlapTail(merged, overlap), unit] : [unit];
    currentLength =
      current.reduce((sum, part) => sum + part.length, 0) + (current.length - 1) * 2;
    currentHasTable = isTable;
  }

  if (current.length > 0) {
    const merged = mergeUnitsText(current);
    if (merged) pushChunk(merged, currentHeadingPath, currentHeading, currentHasTable);
  }

  return chunks;
}

/** Joins paragraph units with a blank line separator, trimming as needed. */
function mergeUnitsText(units: string[]): string {
  return units.join("\n\n").trim();
}

/** Returns the last `count` characters of a chunk (word-boundary trimmed). */
function overlapTail(text: string, count: number): string {
  return text.slice(-count);
}

import type { Tool, ToolResult } from "./types";

/**
 * Phase 7 ΓÇö Calculator Tool.
 *
 * Supports:
 *   - addition          ("2 + 3", "what is 2 plus 3")
 *   - subtraction       ("10 - 4", "minus")
 *   - multiplication    ("6 * 7", "times", "multiply")
 *   - division          ("20 / 5", "divided by", "over")
 *   - percentages       ("what is 20% of 150", "150 * 20%")
 *   - averages          ("average of 4, 8 and 12", "mean of 1 2 3")
 *   - parentheses       ("(2 + 3) * 4")
 *   - decimal numbers
 *
 * The expression is parsed with a small recursive-descent parser ΓÇö `eval` is
 * never used ΓÇö so arbitrary code execution is impossible.
 */

const AVERAGE_RE =
  /\b(?:average|mean|avg)\s+of\s+(.+)$/i;

const PERCENTAGE_OF_RE =
  /\bwhat\s+is\s+([0-9]+(?:\.[0-9]+)?)\s*(?:%|percent)\s+of\s+([0-9]+(?:\.[0-9]+)?)\b/i;

const MATH_KEYWORDS = [
  /[0-9]\s*[+\-*\/^x├ù]\s*[0-9]/i,   // "2+3", "10 / 5"
  /\b(?:plus|minus|times|multiplied\s+by|divided\s+by|over|percent|percentage)\b/i,
  /\b(?:average|mean|avg)\s+of\b/i,
];

/** Token kind produced by the lexer. */
type TokenKind = "number" | "operator" | "lparen" | "rparen" | "eof";

interface Token {
  kind: TokenKind;
  value: string;
  number?: number;
}

/** Converts a math keyword to its symbolic operator. */
function normalizeOperator(word: string): string | null {
  switch (word.toLowerCase()) {
    case "plus":
    case "add":
      return "+";
    case "minus":
    case "subtract":
      return "-";
    case "times":
    case "multiply":
    case "multiplied":
    case "multiplied by":
      return "*";
    case "divide":
    case "divided":
    case "divided by":
    case "over":
      return "/";
    case "x":
    case "├ù":
      return "*";
    default:
      return null;
  }
}

/** Extracts the raw expression from a natural-language sentence. */
function extractExpression(input: string): string | null {
  const trimmed = input.trim();

  // "what is 20% of 150"
  const percentageOf = PERCENTAGE_OF_RE.exec(trimmed);
  if (percentageOf) {
    const amount = Number(percentageOf[1]);
    const base = Number(percentageOf[2]);
    return `(${amount} / 100) * ${base}`;
  }

  // "average of 4, 8 and 12" / "mean of 4 8 12"
  const average = AVERAGE_RE.exec(trimmed);
  if (average) {
    const numbers = extractNumbers(average[1]);
    if (numbers.length >= 2) {
      return `(${numbers.join(" + ")}) / ${numbers.length}`;
    }
    return null;
  }

  // Strip common question prefixes so the parser sees only math.
  let expression = trimmed
    .replace(/^(?:what|whats|what is|calculate|compute|solve|evaluate|find)\s+/i, "")
    .replace(/[?.,!]+$/, "")
    .trim();

  // Replace natural-language operators.
  expression = expression
    .replace(/\b(?:multiplied\s+by|multiply\s+by|divided\s+by|multiplied|divided|plus|minus|times|multiply|divide|over)\b/gi, (match) => {
      return normalizeOperator(match) ?? match;
    })
    .replace(/\bpercent\b/gi, "%")
    .replace(/\bx\b/gi, "*")
    .replace(/[├ù]/g, "*")
    .replace(/\s+/g, " ")
    .trim();

  // Normalize "5%" at the end of an expression to "(5/100)".
  expression = expression.replace(/([0-9]+(?:\.[0-9]+)?)\s*%/g, (_, num) => {
    return `(${num} / 100)`;
  });

  return expression;
}

/** Extracts all decimal numbers from a string (used for averages). */
function extractNumbers(text: string): number[] {
  const matches = text.match(/[0-9]+(?:\.[0-9]+)?/g);
  return (matches ?? []).map((value) => Number(value)).filter((n) => Number.isFinite(n));
}

/**
 * Safe expression evaluator (recursive descent).
 *
 * Grammar:
 *   expr    := term (('+' | '-') term)*
 *   term    := factor (('*' | '/') factor)*
 *   factor  := number | '(' expr ')'
 */
class ExpressionEvaluator {
  private tokens: Token[];
  private position = 0;

  constructor(expression: string) {
    this.tokens = tokenize(expression);
  }

  evaluate(): number {
    const value = this.parseExpression();
    const current = this.tokens[this.position];
    if (current.kind !== "eof") {
      throw new Error(`Unexpected token: ${current.value}`);
    }
    return value;
  }

  private parseExpression(): number {
    let value = this.parseTerm();
    while (true) {
      const token = this.tokens[this.position];
      if (token.kind === "operator" && (token.value === "+" || token.value === "-")) {
        this.position++;
        const right = this.parseTerm();
        value = token.value === "+" ? value + right : value - right;
      } else {
        return value;
      }
    }
  }

  private parseTerm(): number {
    let value = this.parseFactor();
    while (true) {
      const token = this.tokens[this.position];
      if (token.kind === "operator" && (token.value === "*" || token.value === "/")) {
        this.position++;
        const right = this.parseFactor();
        if (token.value === "/" && right === 0) {
          throw new Error("Division by zero");
        }
        value = token.value === "*" ? value * right : value / right;
      } else {
        return value;
      }
    }
  }

  private parseFactor(): number {
    const token = this.tokens[this.position];
    if (token.kind === "number") {
      this.position++;
      return token.number ?? 0;
    }
    if (token.kind === "lparen") {
      this.position++;
      const value = this.parseExpression();
      const closing = this.tokens[this.position];
      if (closing.kind !== "rparen") {
        throw new Error("Missing closing parenthesis");
      }
      this.position++;
      return value;
    }
    throw new Error(`Unexpected token: ${token.value || token.kind}`);
  }
}

/** Splits an expression string into tokens. */
function tokenize(source: string): Token[] {
  const tokens: Token[] = [];
  let index = 0;

  while (index < source.length) {
    const char = source[index];

    if (/\s/.test(char)) {
      index++;
      continue;
    }

    if (/[0-9.]/.test(char)) {
      const match = /^[0-9]+(?:\.[0-9]+)?/.exec(source.slice(index));
      if (!match) throw new Error(`Invalid number near: ${source.slice(index, index + 10)}`);
      tokens.push({ kind: "number", value: match[0], number: Number(match[0]) });
      index += match[0].length;
      continue;
    }

    if ("+-*/".includes(char)) {
      tokens.push({ kind: "operator", value: char });
      index++;
      continue;
    }

    if (char === "(") {
      tokens.push({ kind: "lparen", value: char });
      index++;
      continue;
    }

    if (char === ")") {
      tokens.push({ kind: "rparen", value: char });
      index++;
      continue;
    }

    throw new Error(`Unexpected character: ${char}`);
  }

  tokens.push({ kind: "eof", value: "" });
  return tokens;
}

/** Formats a numeric result (strips trailing zeros, handles integers). */
function formatNumber(value: number): string {
  if (!Number.isFinite(value)) {
    throw new Error("Result is not a finite number");
  }
  const rounded = Math.round(value * 1e10) / 1e10;
  return String(rounded);
}

/** Detects whether a message might be a math request. */
function canHandle(input: string): boolean {
  const text = input.toLowerCase();
  return (
    AVERAGE_RE.test(text) ||
    PERCENTAGE_OF_RE.test(text) ||
    MATH_KEYWORDS.some((pattern) => pattern.test(text))
  );
}

/** Executes the calculator tool. */
async function execute(input: string): Promise<ToolResult> {
  const started = performance.now();

  const extracted = extractExpression(input);
  if (!extracted) {
    return {
      success: false,
      toolId: "calculator",
      output: "",
      executionTime: performance.now() - started,
    };
  }

  try {
    const evaluator = new ExpressionEvaluator(extracted);
    const value = evaluator.evaluate();
    const output = formatNumber(value);

    return {
      success: true,
      toolId: "calculator",
      output: `Calculation result: ${output}`,
      metadata: {
        label: "≡ƒº« Calculator",
        summary: `Computed: ${extracted} = ${output}`,
        data: { expression: extracted, result: output },
      },
      executionTime: performance.now() - started,
    };
  } catch (error) {
    return {
      success: false,
      toolId: "calculator",
      output: "",
      metadata: {
        label: "≡ƒº« Calculator",
        summary: "Unable to parse the math expression.",
      },
      executionTime: performance.now() - started,
    };
  }
}

/** The Calculator tool instance. */
export const calculatorTool: Tool = {
  id: "calculator",
  name: "Calculator",
  description:
    "Performs arithmetic: addition, subtraction, multiplication, division, percentages, and averages.",
  // Empty = available to all agents.
  enabledAgents: [],
  inputSchema: {
    type: "object",
    properties: {
      expression: {
        type: "string",
        description: "The math expression or natural-language math question.",
      },
    },
    required: ["expression"],
  },
  canHandle,
  execute,
};

